// Lenis minimal stub — smooth scroll raf polyfill
(function () {
  'use strict';
  window.Lenis = window.Lenis || class Lenis {
    constructor(opts) { this.opts = opts || {}; }
    on() {}
    off() {}
    scrollTo() {}
    resize() {}
    destroy() {}
    raf(time) { requestAnimationFrame((t) => this.raf(t)); }
  };
  if (typeof window.__lenisInitialized === 'undefined') {
    window.__lenisInitialized = true;
    new window.Lenis().raf();
  }
})();
